sys_script_client.script:
function onLoad() {
    var category = g_form.getValue('category_aml');
    var subcat = g_form.getValue('sub_category');

    // Related list names
    var eeLists = [
        'REL:7f1724731bbe6e106ed00e1ad34bcb85', //ER List
        'REL:93dd9dfc1b6b6690cf016467b04bcbfb', //Connected Person
        'REL:0c8d9dbc1b6b6690cf016467b04bcb7c', //Director
        'REL:ecb855341b6b6690cf016467b04bcb78'  //Beneficial ownner
    ];
    var erList = 'REL:3ab688bf1b76e6509e88ed32b24bcb78'; //EE List

    if (category == 'new_enrollment') {
        g_form.hideRelatedList('x_hsb11_mss_trus_0_aml_kyc_case_task.aml_kyc_case'); // AML/KYC Case Task
        if (subcat == 'ee') {
            eeLists.forEach(function(list) { g_form.hideRelatedList(list); });
        } else if (subcat == 'er') {
            g_form.hideRelatedList(erList);
        }
    } else if (category == 'periodic_review_query') {
        if (subcat == 'ee') {
            eeLists.forEach(function(list) { g_form.hideRelatedList(list); });
        } else if (subcat == 'er') {
            g_form.hideRelatedList(erList);
        }
    } else if (category.includes('rule')) {
        // Hide all except the first for 'ee', only erList for 'er'
        eeLists.slice(1).forEach(function(list) { g_form.hideRelatedList(list); });
        if (subcat == 'ee') {
            g_form.hideRelatedList(eeLists[0]);
        } else if (subcat == 'er') {
            g_form.hideRelatedList(erList);
        }
    }
}
